      "evidence": ["drivers.bz_min_hourly_nT", "drivers.bz_min_time"]
    },
    {
      "statement": "Ordinary solar wind speed of 507 km/s",
      "evidence": ["drivers.speed_max_km_per_s"]
    },
    {
      "statement": "Solar activity was low with an F10.7 index of 79 sfu",
      "evidence": ["solar.f107_mean_sfu", "solar.level"]
